param()
$ErrorActionPreference='Stop';$root=$PSScriptRoot;$input=Join-Path $root 'input';$sources=@('source-a','source-b','source-c');foreach($s in $sources){New-Item -ItemType Directory -Force -Path (Join-Path $input $s)|Out-Null};Set-Content (Join-Path $input 'source-a\attendance.pdf') 'Sample PDF fixture for the local file organizer.';Set-Content (Join-Path $input 'source-a\notes.txt') 'Sample TXT fixture for the local file organizer.';Set-Content (Join-Path $input 'source-b\attendance.pdf') 'Duplicate-name PDF fixture from a different source folder.';Set-Content (Join-Path $input 'source-b\photo.png') 'Sample PNG fixture for extension classification.';Set-Content (Join-Path $input 'source-c\brief.docx') 'Sample DOCX-named fixture for extension classification.';Set-Content (Join-Path $input 'source-c\budget.xlsx') 'Sample XLSX-named fixture for extension classification.';Set-Content (Join-Path $input 'source-c\readme.md') 'Unsupported extension intentionally left in place and logged as skipped.';Write-Output "Restored sample source files under $input"
